import{_ as r,C as l,o as n,c as d,j as o,a as i,E as e,a2 as s}from"./chunks/framework.DGvnA5EY.js";const u="/workbuddy-guide/assets/00-hei-intro.2Gs_jHDS.png",k=JSON.parse('{"title":"本篇导读 · 第四篇 岗位与行业落地","description":"> 内容来源：WorkBuddy 官方指南与社区实战案例整理（非官方，© 本指南作者，保留所有权利） 前三篇你练的是\\"内功\\"：会用工具、跑过案例、有自己的系统。第四篇回答一个更 现实的问题——这套内功怎么变现：要么在你的岗位上做出别人做不出的成绩， 要么沉淀成一个行业能用的工作流，甚至长成一门生意。","frontmatter":{"title":"本篇导读 · 第四篇 岗位与行业落地"},"headers":[],"relativePath":"bluebook/第四篇 岗位与行业落地/index.md","filePath":"bluebook/第四篇 岗位与行业落地/index.md","lastUpdated":1791629861000}'),h={name:"bluebook/第四篇 岗位与行业落地/index.md"};function p(q,t,b,g,m,c){const a=l("Paywall");return n(),d("div",null,[t[0]||(t[0]=o("h1",{id:"本篇导读-·-第四篇-岗位与行业落地",tabindex:"-1"},[i("本篇导读 · 第四篇 岗位与行业落地 "),o("a",{class:"header-anchor",href:"#本篇导读-·-第四篇-岗位与行业落地","aria-label":'Permalink to "本篇导读 · 第四篇 岗位与行业落地"'},"​")],-1)),t[1]||(t[1]=o("blockquote",null,[o("p",null,"内容来源：WorkBuddy 官方指南与社区实战案例整理（非官方，© 本指南作者，保留所有权利）")],-1)),e(a,{part:"4",variant:"banner"}),t[2]||(t[2]=s('<p>前三篇你练的是&quot;内功&quot;：会用工具、跑过案例、有自己的系统。第四篇回答一个更 现实的问题——<strong>这套内功怎么变现</strong>：要么在你的岗位上做出别人做不出的成绩， 要么沉淀成一个行业能用的工作流，甚至长成一门生意。</p><p><img src="'+u+'" alt="一只小黑推开一扇门，走进一座纸做的办公城市" loading="lazy"></p><p><em>配图为示意插画，用于帮助理解本篇主题，与实际软件界面无关。</em></p><h2 id="本篇的三个台阶" tabindex="-1">本篇的三个台阶 <a class="header-anchor" href="#本篇的三个台阶" aria-label="Permalink to &quot;本篇的三个台阶&quot;">​</a></h2><table tabindex="0"><thead><tr><th>章节</th><th>回答什么问题</th><th>核心方法</th></tr></thead><tbody><tr><td>第 26 章 · 岗位路线图</td><td><strong>你的岗位</strong>怎么用深</td><td>每个岗位的高频任务 × Skill 组合 × 进阶方向</td></tr><tr><td>第 27 章 · 行业路线图</td><td><strong>你的行业</strong>怎么吃透</td><td>通用能力 × 行业知识库 = 行业工作流</td></tr><tr><td>第 28 章 · 组建 AI 团队</td><td><strong>一个人的极限</strong>怎么突破</td><td>把前四篇全部串成一支&quot;AI 团队&quot; + 经营视角</td></tr></tbody></table><h2 id="为什么顺序是-岗位-→-行业-→-团队" tabindex="-1">为什么顺序是&quot;岗位 → 行业 → 团队&quot; <a class="header-anchor" href="#为什么顺序是-岗位-→-行业-→-团队" aria-label="Permalink to &quot;为什么顺序是&quot;岗位 → 行业 → 团队&quot;&quot;">​</a></h2><ul><li><strong>岗位</strong>是你已经站住的地方，改变成本最低、反馈最快——先用它证明价值；</li><li><strong>行业</strong>是岗位的放大器：把岗位上验证过的工作流抽象出来，同行业谁都能用， 你的价值就从&quot;会用工具的人&quot;变成&quot;有方法论的人&quot;；</li><li><strong>团队</strong>是终局：当你有岗位成绩、有行业工作流，就需要一支 AI 团队 （和真实协作关系）把这一切规模化。</li></ul><h2 id="使用本篇的正确姿势" tabindex="-1">使用本篇的正确姿势 <a class="header-anchor" href="#使用本篇的正确姿势" aria-label="Permalink to &quot;使用本篇的正确姿势&quot;">​</a></h2><ol><li><strong>先对号入座</strong>：第 26 章找到你的岗位（或最接近的），按表装技能、跑任务；</li><li><strong>再建行业底座</strong>：第 27 章的行业知识库方法，是本篇含金量最高的可迁移资产；</li><li><strong>最后画组织图</strong>：第 28 章教你把自己会用的一切，变成一支分工明确的团队。</li></ol><blockquote><p>本篇的每章都延续了前篇的&quot;零成本&quot;思路：不新增任何付费依赖， 全部用你已经装过的能力和免费的官方技能完成。</p></blockquote><h2 id="本篇任务总清单" tabindex="-1">本篇任务总清单 <a class="header-anchor" href="#本篇任务总清单" aria-label="Permalink to &quot;本篇任务总清单&quot;">​</a></h2><ul><li>[ ] 在第 26 章找到自己的岗位，跑通 2 个岗位专属任务</li><li>[ ] 用第 27 章的方法建一个 20 条以上的行业知识库</li><li>[ ] 画出自己的第一张&quot;AI 团队组织图&quot;（第 28 章）</li><li>[ ] 用一句话说清你的 AI 能力能替谁、省下什么、创造什么</li></ul><hr><p><em>下一篇：第 26 章 岗位路线图——从你的岗位开始。</em></p>',14)),e(a,{part:"4"}),t[3]||(t[3]=o("p",null,[o("em",null,"—— 以上试读到此为止。第四篇共 3 章，完整版（飞书文档）包含全部实操内容。——")],-1))])}const x=r(h,[["render",p]]);export{k as __pageData,x as default};
